skPat.zig = (c, at = 60, w = 7) => ({ cx, y0 }) => [ln(`M${cx - 330},${y0 + at} ${[...Array(22)].map(() => 'l15,-18 l15,18').join(' ')}`, w, c)];
skPat.checks = (c, s = 30) => ({ cx, y0 }) => { let o = ''; for (let j = 0; j < 14; j++) for (let i = 0; i < 9; i++) o += `<rect x="${cx - 270 + i * s * 2 + (j % 2) * s}" y="${y0 + j * s}" width="${s}" height="${s}" fill="${c}"/>`; return [`<g opacity=".9">${o}</g>`]; };
skPat.floral = (c, c2 = GOLD) => ({ cx, y0 }) => { let o = ''; for (let j = 0; j < 6; j++) for (let i = 0; i < 7; i++) { const x = cx - 190 + i * 64 + (j % 2) * 32, y = y0 + 40 + j * 50; o += [0, 1, 2, 3, 4].map(k => `<circle cx="${f(x + Math.cos(k * 1.257) * 8)}" cy="${f(y + Math.sin(k * 1.257) * 8)}" r="6.5" fill="${(i + j) % 2 ? c2 : c}" stroke="${INK}" stroke-width="1.6"/>`).join('') + `<circle cx="${x}" cy="${y}" r="4" fill="#fff"/>`; } return [o]; };
skPat.vstripes = (c, n = 11, w = 16) => ({ cx, y0 }) => [...Array(n)].map((_, i) => `<path d="M${cx - 170 + i * 34},${y0} l${w},0 l${(i - n / 2) * 5},500 l${-w},0 Z" fill="${c}" opacity=".9"/>`);
skPat.lace = (c = WHITE, at = 100) => ({ cx, y0 }) => [`<path d="M${cx - 330},${y0 + at} ${[...Array(22)].map(() => 'q15,22 30,0').join(' ')} L${cx + 330},${y0 + at - 14} L${cx - 330},${y0 + at - 14} Z" fill="${c}" stroke="${INK}" stroke-width="2.4"/>`, ...[...Array(22)].map((_, i) => `<circle cx="${cx - 315 + i * 30}" cy="${y0 + at + 2}" r="2.6" fill="${INK}" opacity=".5"/>`)];
skPat.stars = (c = GOLD) => ({ cx, y0 }) => { let o = ''; for (let j = 0; j < 7; j++) for (let i = 0; i < 7; i++) o += `<path d="${poly(starPts(cx - 190 + i * 64 + (j % 2) * 32, y0 + 40 + j * 46, 10))}" fill="${c}"/>`; return [o]; };
skPat.ombre = (c) => ({ cx, y0, defs }) => { if (!defs) return []; const id = nid('o'); defs.push(`<linearGradient id="${id}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${c}" stop-opacity="0"/><stop offset="1" stop-color="${c}"/></linearGradient>`); return [`<rect x="${cx - 400}" y="${y0 + 20}" width="800" height="300" fill="url(#${id})"/>`]; };
export { PART, EMB, SK, skPat, cape, wings, LEN, GOLD, STEEL, LEATHER, WHITE, BLACK, RED, SKIN };
export const OUTFITS = {};
// O(key, label, group, gender, palette, parts, extra): extra = { skirt: (P) => SK(...), behind: (P) => cape(...), metal, backEmb }
export const O = (key, label, group, g, pal, parts, extra = {}) => { OUTFITS[key] = { key, label, group, g, pal, parts, ...extra }; };
const resolve = (v, P) => typeof v === 'string' && v.length <= 2 && P[v] ? P[v] : Array.isArray(v) ? v.map(x => resolve(x, P)) : v;
// dress(S, key, pal): put an outfit on a built character S (buildChar result). pal overrides { a, b, c, m, l }.
export function dress(S, key, pal = {}) { const of = typeof key === 'string' ? OUTFITS[key] : key; if (!of) throw new Error('no outfit ' + key);
  const P = { a: of.pal[0], b: of.pal[1] || WHITE, c: of.pal[2] || GOLD, m: STEEL, l: LEATHER, ...pal };
  const draw = back => ctx => { const A = mkA(ctx, P, back); A.backEmb = of.backEmb; const out = [];
    for (const [name, ...args] of of.parts) { if (back && !BACKOK.has(name)) continue; if (!PART[name]) throw new Error('no part ' + name); out.push(...PART[name](A, ...args.map(a => resolve(a, P)))); }
    return [...out, ...finish(A, of)]; };
  S.coat = P.a; S.details = draw(false); S.backDetails = draw(true);
  if (of.skirt) S.skirt = of.skirt(P); else delete S.skirt;
  if (of.behind) S.behind = of.behind(P);
  return S; }
